+#[derive(Debug, Error)]
+pub enum LlmError {
+    #[error("网络请求失败：{0}")]
+    Http(#[from] reqwest::Error),
+    #[error("API 返回错误（HTTP {status}）：{message}")]
+    Api { status: u16, message: String },
+    #[error("响应流解析失败：{0}")]
+    Stream(String),
+    #[error(
+        "预算已耗尽（已花 {spent}，上限 {limit}），任务中断。可在配置中调整 [budget] limit 后重试"
+    )]
+    BudgetExceeded { spent: Decimal, limit: Decimal },
+    #[error("任务已被用户取消")]
+    Cancelled,
+}
