+
+    /// 测试（§13 Fake 注入）与离线演示用：替换底层客户端实现。
+    #[allow(dead_code)]
+    pub fn with_client(
+        client: Arc<dyn LlmClient>,
+        model_name: impl Into<String>,
+        budget_limit: Decimal,
+        ledger: Arc<SpendLedger>,
+        bus: EventBus,
+    ) -> Self {
+        Self {
+            client,
+            model_name: model_name.into(),
