        let err = cfg.validate().unwrap_err();
        assert!(err.to_string().contains("endpoint"));
    }

    #[test]
    fn 模板可被解析() {
        let cfg: AppConfig = toml::from_str(&render_template()).unwrap();
        assert_eq!(cfg.model.model, "glm-5.2");
        assert_eq!(cfg.model.context_len, 128_000);
    }
}

