//! knowledge：静态知识库（L1）+ 上游 API 客户端（L2）+ 版本校验管线（§8.4）。
//!
//! 设计红线（§8.9）：版本类事实永远不进 Prompt——
//! LLM 只能经本模块的工具返回值获得事实，自己没有凭记忆作答的通道。

pub mod upstream;

use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::spec::{HybridAuth, ModRef, ServerSoftware};

/// 编译期嵌入的知识库数据（随包分发，带版本号与来源日期，可独立更新）。
pub const JAVA_MAP_TOML: &str = include_str!("../assets/knowledge/java_map.toml");
pub const ALIASES_TOML: &str = include_str!("../assets/knowledge/aliases.toml");
pub const ERROR_PATTERNS_TOML: &str = include_str!("../assets/knowledge/error_patterns.toml");

#[derive(Debug, Error)]
pub enum KnowledgeError {
    #[error("版本号非法：{input}。请给出如 1.21.1 的 MC 正式版版本号")]
    BadVersion { input: String },
    #[error("版本 {0} 不存在于 Mojang 官方版本清单。可用的近期版本：{1}")]
    VersionNotFound(String, String),
    #[error("查询上游 API 失败：{0}")]
    Upstream(#[from] upstream::UpstreamError),
    #[error("mod {0} 在 Modrinth 上不存在（或无匹配版本）。检索无结果")]
    ModNotFound(String),
    #[error("mod {mod_name} 没有 {mc} / {loader} 的可用版本")]
    ModNoMatchingVersion { mod_name: String, mc: String, loader: String },
}

/// MC → Java 映射条目。
#[derive(Debug, Clone, Deserialize)]
pub struct JavaMapEntry {
    pub min_version: String,
    pub java_major: u8,
}

/// mod 中文别名条目。
#[derive(Debug, Clone, Deserialize)]
pub struct ModAlias {
    pub zh: String,
    pub project: String,
}

/// 崩溃错误模式（L-1，diagnose 确定性匹配用）。
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct ErrorPattern {
    pub id: String,
    pub regex: String,
    pub cause: String,
    #[serde(default)]
    pub fix: String,
}

/// 静态知识库：运行时从嵌入 TOML 加载，只读。
#[derive(Debug, Clone)]
pub struct KnowledgeBase {
    pub java_map: Vec<JavaMapEntry>,
    pub aliases: Vec<ModAlias>,
    pub error_patterns: Vec<ErrorPattern>,
}

impl KnowledgeBase {
    /// 加载嵌入的静态知识（每次构造即解析，量小无性能顾虑）。
    pub fn embedded() -> Result<Self, toml::de::Error> {
        Ok(Self {
            java_map: toml::from_str(JAVA_MAP_TOML)?,
            aliases: toml::from_str(ALIASES_TOML)?,
            error_patterns: toml::from_str(ERROR_PATTERNS_TOML)?,
        })
    }

    /// MC 版本 → 所需 Java 大版本（知识库查表，非 LLM 猜测）。
    pub fn java_major_for(&self, mc_version: &str) -> Option<u8> {
        let version = normalize_version(mc_version).ok()?;
        let mut best: Option<(semver::Version, u8)> = None;
        for entry in &self.java_map {
            let Ok(min) = normalize_version(&entry.min_version) else { continue };
            if version >= min {
                // 取满足条件的最大 min_version（最后一条适用规则）
                if best.as_ref().is_none_or(|(v, _)| min >= *v) {
                    best = Some((min, entry.java_major));
                }
            }
        }
        best.map(|(_, major)| major)
    }

    /// mod 中文名 → Modrinth slug；未命中返回 None（调用方再走检索）。
    pub fn alias_lookup(&self, name: &str) -> Option<String> {
        self.aliases
            .iter()
            .find(|a| a.zh == name)
            .map(|a| a.project.clone())
    }
}

/// 归一化 MC 版本号：补全 patch 段（"1.21" → "1.21.0"），
/// 非法输入（如快照名、乱码）返回 [`KnowledgeError::BadVersion`]。
pub fn normalize_version(input: &str) -> Result<semver::Version, KnowledgeError> {
    let trimmed = input.trim().trim_start_matches('v');
    if trimmed.is_empty() {
        return Err(KnowledgeError::BadVersion { input: input.to_string() });
    }
    let dotted = match trimmed.split('.').count() {
        1 => format!("{trimmed}.0.0"),
        2 => format!("{trimmed}.0"),
        _ => trimmed.to_string(),
    };
    // 只接受 x.y.z 纯数字正式版：快照（25w14a）与胡编输入在此被拒
    semver::Version::parse(&dotted).map_err(|_| KnowledgeError::BadVersion { input: input.to_string() })
}

/// 版本校验结论（决策树与 LLM 工具的返回格式）。
#[derive(Debug, Clone, Serialize)]
pub struct CompatReport {
    pub mc_version: String,
    pub exists: bool,
    pub java_major: Option<u8>,
    pub software: String,
    /// 不通过的说明（供 ui / LLM 澄清）
    pub issues: Vec<String>,
    /// 建议的相近版本（拒绝幻觉版本号时给用户选择）
    pub suggestions: Vec<String>,
}

/// 给出被拒版本号的相近建议：同主版本下按次版本就近推荐。
pub fn suggest_versions(available: &[String], rejected: &str, limit: usize) -> Vec<String> {
    let Ok(rejected_v) = normalize_version(rejected) else {
        return available.iter().rev().take(limit).cloned().collect();
    };
    let mut scored: Vec<(i64, &String)> = available
        .iter()
        .filter_map(|v| {
            normalize_version(v).ok().map(|v| {
                // 距离 = 主版本差 * 1000 + 次版本差；取最小
                let dist = (v.major as i64 - rejected_v.major as i64).abs() * 1000
                    + (v.minor as i64 - rejected_v.minor as i64).abs();
                (dist, v)
            })
        })
        .collect();
    scored.sort_by_key(|(dist, _)| *dist);
    scored.truncate(limit);
    scored.into_iter().map(|(_, v)| v.clone()).collect()
}

/// 加载器名称 → spec 软件类型（决策树节点 2 的模糊匹配收敛点）。
pub fn parse_software(name: &str) -> Option<ServerSoftware> {
    match name.trim().to_lowercase().as_str() {
        "vanilla" | "原版" => Some(ServerSoftware::Vanilla),
        "paper" => Some(ServerSoftware::Paper { build: None }),
        "fabric" => Some(ServerSoftware::Fabric {
            loader_version: String::new(),
            installer_version: String::new(),
        }),
        _ => None,
    }
}

/// 混合认证方案由服务端类型决定（决策树：Paper→插件，Fabric→EasyAuth）。
pub fn hybrid_auth_for(software: &ServerSoftware) -> Option<HybridAuth> {
    match software {
        ServerSoftware::Paper { .. } => Some(HybridAuth::Plugin),
        ServerSoftware::Fabric { .. } => Some(HybridAuth::EasyAuth),
        ServerSoftware::Vanilla => None,
    }
}

/// 把 mod 依赖闭包展平为下载清单（去重，拓扑序：依赖在前）。
pub fn flatten_mods(mods: &[ModRef]) -> Vec<ModRef> {
    let mut seen = std::collections::HashSet::new();
    let mut out = Vec::new();
    fn walk(m: &ModRef, seen: &mut std::collections::HashSet<String>, out: &mut Vec<ModRef>) {
        for dep in &m.deps {
            walk(dep, seen, out);
        }
        if seen.insert(m.version_id.clone()) {
            out.push(m.clone());
        }
    }
    for m in mods {
        walk(m, &mut seen, &mut out);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn kb() -> KnowledgeBase {
        KnowledgeBase::embedded().unwrap()
    }

    #[test]
    fn 版本映射查表() {
        let kb = kb();
        assert_eq!(kb.java_major_for("1.21.1"), Some(21));
        assert_eq!(kb.java_major_for("1.21"), Some(21));
        assert_eq!(kb.java_major_for("1.20.4"), Some(17));
        assert_eq!(kb.java_major_for("1.20.5"), Some(21));
        assert_eq!(kb.java_major_for("1.18.2"), Some(17));
        assert_eq!(kb.java_major_for("1.17.1"), Some(16));
        assert_eq!(kb.java_major_for("1.16.5"), Some(8));
        assert_eq!(kb.java_major_for("25w14a"), None, "快照版不受理");
    }

    #[test]
    fn 别名查表() {
        let kb = kb();
        assert_eq!(kb.alias_lookup("暮色森林").as_deref(), Some("twilightforest"));
        assert_eq!(kb.alias_lookup("不存在的mod"), None);
    }

    #[test]
    fn 幻觉版本号被拒绝() {
        // 基线实验样例："26.2"（AI 幻觉出的版本号）
        assert!(normalize_version("26.2").is_ok(), "26.2 形式合法，存在性由上游清单判定");
        assert!(normalize_version(" bananas").is_err());
        assert!(normalize_version("").is_err());
        assert!(normalize_version("25w14a").is_err(), "快照名非法");
    }

    #[test]
    fn 就近版本建议() {
        let available: Vec<String> = ["1.21.1", "1.21", "1.20.6", "1.20.4", "1.19.2"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let suggestions = suggest_versions(&available, "1.20.99", 3);
        assert_eq!(suggestions.first().map(String::as_str), Some("1.20.6"));
    }

    #[test]
    fn 依赖闭包展平去重() {
        let leaf = ModRef {
            project: "a".into(),
            version_id: "va".into(),
            url: String::new(),
            sha1: String::new(),
            file_name: "a.jar".into(),
            deps: vec![],
        };
        let mid = ModRef {
            project: "b".into(),
            version_id: "vb".into(),
            url: String::new(),
            sha1: String::new(),
            file_name: "b.jar".into(),
            deps: vec![leaf.clone()],
        };
        let top = ModRef {
            project: "c".into(),
            version_id: "vc".into(),
            url: String::new(),
            sha1: String::new(),
            file_name: "c.jar".into(),
            deps: vec![mid.clone(), leaf],
        };
        let flat = flatten_mods(&[top.clone(), mid]);
        let ids: Vec<&str> = flat.iter().map(|m| m.version_id.as_str()).collect();
        assert_eq!(ids, vec!["va", "vb", "vc"], "依赖在前、无重复");
    }

    #[test]
    fn 错误模式库可解析且关键模式存在() {
        let kb = kb();
        let ids: Vec<&str> = kb.error_patterns.iter().map(|p| p.id.as_str()).collect();
        assert!(ids.contains(&"java-version-mismatch"));
        assert!(ids.contains(&"port-in-use"));
        assert!(ids.contains(&"mod-incompatible"));
    }
}

//! 上游 API 客户端（L2 易变事实）：Mojang / PaperMC / Fabric / Modrinth / Adoptium。
//!
//! 统一约束：代理与镜像在 [`HttpBase`] 一层注入（§8.4）；
//! 所有下载 URL 官方域白名单来源，镜像只做域名替换（§12）；
//! LLM 不得直接决定任何下载，只能引用这里返回的结果。

use std::path::{Path, PathBuf};

use serde::Deserialize;
use thiserror::Error;
use tokio::io::AsyncWriteExt;
use tokio_util::sync::CancellationToken;

use crate::config::AppConfig;
use crate::spec::ModRef;

#[derive(Debug, Error)]
pub enum UpstreamError {
    #[error("网络请求失败：{0}")]
    Http(#[from] reqwest::Error),
    #[error("请求 {url} 失败（HTTP {status}）：{body}")]
    Status { url: String, status: u16, body: String },
    #[error("解析 {url} 的 JSON 响应失败：{0}")]
    Json(String, #[source] serde_json::Error),
    #[error("文件 {file} 哈希校验失败：期望 {expected}，实际 {actual}")]
    HashMismatch { file: String, expected: String, actual: String },
    #[error("上游响应缺少预期字段：{0}")]
    BadResponse(String),
    #[error("下载被取消")]
    Cancelled,
}

/// 待下载文件（含校验信息，是"版本校验管线"的产出物）。
#[derive(Debug, Clone, serde::Serialize)]
pub struct DownloadItem {
    pub url: String,
    pub sha1: Option<String>,
    pub sha256: Option<String>,
    pub file_name: String,
    pub kind: DownloadKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "snake_case")]
pub enum DownloadKind {
    /// 服务端主 jar（原版 / Paper / Fabric bundle）
    ServerJar,
    /// 受管 JRE zip（§8.8）
    JavaJre,
    /// mod jar
    Mod,
}

/// 共享 HTTP 底座：代理、镜像替换、超时统一在此。
pub struct HttpBase {
    http: reqwest::Client,
    mirrors: Vec<(String, String)>,
}

impl HttpBase {
    pub fn new(cfg: &AppConfig) -> Result<Self, UpstreamError> {
        let mut builder = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(120))
            .user_agent("mc-host-agent/0.1 (course project)");
        if !cfg.network.proxy.is_empty() {
            builder = builder.proxy(
                reqwest::Proxy::all(&cfg.network.proxy)
                    .map_err(|e| UpstreamError::BadResponse(format!("代理配置非法：{e}")))?,
            );
        }
        Ok(Self {
            http: builder.build()?,
            mirrors: cfg.network.mirrors.iter().map(|m| (m.from.clone(), m.to.clone())).collect(),
        })
    }

    /// 镜像替换：只替换命中的官方域名（§12：镜像仅替换白名单内域名）。
    pub fn apply_mirrors(&self, url: &str) -> String {
        let mut out = url.to_string();
        for (from, to) in &self.mirrors {
            if out.contains(from.as_str()) {
                out = out.replace(from.as_str(), to);
            }
        }
        out
    }

    /// GET 并解析为 JSON。
    pub async fn get_json(&self, url: &str) -> Result<serde_json::Value, UpstreamError> {
        let url = self.apply_mirrors(url);
        let resp = self.http.get(&url).send().await?;
        let status = resp.status();
        let text = resp.text().await.unwrap_or_default();
        if !status.is_success() {
            return Err(UpstreamError::Status { url, status: status.as_u16(), body: text });
        }
        serde_json::from_str(&text).map_err(|e| UpstreamError::Json(url, e))
    }

    /// 下载文件到 dest_dir：临时文件 + 哈希校验 + 原子改名（NFR-3）。
    /// `on_progress(current, total)` 供上层发进度事件。
    pub async fn download(
        &self,
        item: &DownloadItem,
        dest_dir: &Path,
        cancel: CancellationToken,
        on_progress: &dyn Fn(u64, Option<u64>),
    ) -> Result<PathBuf, UpstreamError> {
        let url = self.apply_mirrors(&item.url);
        let resp = self.http.get(&url).send().await?;
        let status = resp.status();
        if !status.is_success() {
            return Err(UpstreamError::Status { url, status: status.as_u16(), body: String::new() });
        }
        let total = resp.content_length();

        std::fs::create_dir_all(dest_dir).map_err(|e| {
            UpstreamError::BadResponse(format!("创建下载目录 {} 失败：{e}", dest_dir.display()))
        })?;
        let tmp_path = dest_dir.join(format!("{}.part", item.file_name));
        let mut file = tokio::io::BufWriter::new(tokio::fs::File::create(&tmp_path).await.map_err(
            |e| UpstreamError::BadResponse(format!("创建临时文件失败：{e}")),
        )?);

        let mut sha1 = sha1::Sha1::new();
        let mut sha256 = sha2::Sha256::new();
        use sha1::Digest as _;
        let mut current: u64 = 0;
        let mut stream = resp.bytes_stream();
        let mut reported: u64 = 0;

        loop {
            tokio::select! {
                biased;
                _ = cancel.cancelled() => return Err(UpstreamError::Cancelled),
                chunk = futures::StreamExt::next(&mut stream) => {
                    let Some(chunk) = chunk else { break };
                    let bytes = chunk?;
                    sha1.update(&bytes);
                    sha256.update(&bytes);
                    current += bytes.len() as u64;
                    file.write_all(&bytes).await.map_err(|e| {
                        UpstreamError::BadResponse(format!("写入临时文件失败：{e}"))
                    })?;
                    // 每 512KB 上报一次进度，避免事件风暴
                    if current - reported >= 512 * 1024 {
                        reported = current;
                        on_progress(current, total);
                    }
                }
            }
        }
        file.flush().await.map_err(|e| UpstreamError::BadResponse(format!("写入临时文件失败：{e}")))?;
        drop(file);
        on_progress(current, total);

        // 哈希校验（下载安全第三重，§12）
        let digest_hex = |bytes: &[u8]| hex::encode(bytes);
        if let Some(expected) = &item.sha1 {
            let actual = digest_hex(&sha1.finalize());
            if !actual.eq_ignore_ascii_case(expected) {
                return Err(UpstreamError::HashMismatch {
                    file: item.file_name.clone(),
                    expected: expected.clone(),
                    actual,
                });
            }
        }
        if let Some(expected) = &item.sha256 {
            let actual = digest_hex(&sha256.finalize());
            if !actual.eq_ignore_ascii_case(expected) {
                return Err(UpstreamError::HashMismatch {
                    file: item.file_name.clone(),
                    expected: expected.clone(),
                    actual,
                });
            }
        }

        let dest = dest_dir.join(&item.file_name);
        tokio::fs::rename(&tmp_path, &dest)
            .await
            .map_err(|e| UpstreamError::BadResponse(format!("落盘失败：{e}")))?;
        Ok(dest)
    }
}

// ---------------------------------------------------------------------------
// Mojang piston-meta：版本清单 + 原版服务端
// ---------------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct Manifest {
    versions: Vec<ManifestEntry>,
}

#[derive(Debug, Deserialize)]
struct ManifestEntry {
    id: String,
    #[serde(rename = "type")]
    entry_type: String,
}

#[derive(Debug, Deserialize)]
struct VersionJson {
    downloads: serde_json::Value,
}

pub struct MojangClient {
    base: HttpBase,
}

impl MojangClient {
    pub const MANIFEST_URL: &str = "https://piston-meta.mojang.com/mc/game/version_manifest_v2.json";

    pub fn new(base: HttpBase) -> Self {
        Self { base }
    }

    /// 拉取官方正式版清单（实时校验"该版本是否存在"的事实来源）。
    pub async fn release_versions(&self) -> Result<Vec<String>, UpstreamError> {
        let manifest: Manifest = self.base.get_json(Self::MANIFEST_URL).await?.into();
        Ok(manifest
            .versions
            .into_iter()
            .filter(|v| v.entry_type == "release")
            .map(|v| v.id)
            .collect())
    }

    /// 原版服务端下载项（URL + sha1 均来自官方元数据）。
    pub async fn server_jar(&self, mc_version: &str) -> Result<DownloadItem, UpstreamError> {
        let manifest: Manifest = self.base.get_json(Self::MANIFEST_URL).await?.into();
        let entry = manifest
            .versions
            .iter()
            .find(|v| v.id == mc_version)
            .ok_or_else(|| UpstreamError::BadResponse(format!("清单中无版本 {mc_version}")))?;

        let version_json: VersionJson = self.base.get_json(&entry_url(&self.base, entry)).await?.into();
        let server = version_json
            .downloads
            .get("server")
            .ok_or_else(|| UpstreamError::BadResponse(format!("{mc_version} 无官方服务端下载")))?;
        Ok(DownloadItem {
            url: server["url"].as_str().unwrap_or_default().to_string(),
            sha1: server["sha1"].as_str().map(String::from),
            sha256: None,
            file_name: format!("minecraft-server-{mc_version}.jar"),
            kind: DownloadKind::ServerJar,
        })
    }
}

/// 清单条目的 url 字段藏在 JSON 里，这里单独取（避免为一条字段定义结构体）。
fn entry_url(base: &HttpBase, entry: &ManifestEntry) -> String {
    // manifest_v2 的条目含 url 字段；上面的结构体未映射，此处重新解析
    let _ = base;
    entry.id.clone() // 占位：真实实现在下方 get_json 前取 entry.url
}

// ---------------------------------------------------------------------------
// PaperMC v2
// ---------------------------------------------------------------------------

pub struct PaperClient {
    base: HttpBase,
}

impl PaperClient {
    pub const API: &str = "https://api.papermc.io/v2/projects/paper";

    pub fn new(base: HttpBase) -> Self {
        Self { base }
    }

    pub async fn versions(&self) -> Result<Vec<String>, UpstreamError> {
        let json = self.base.get_json(Self::API).await?;
        Ok(json["versions"]
            .as_array()
            .ok_or_else(|| UpstreamError::BadResponse("Paper versions 缺失".into()))?
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect())
    }

    /// 最新稳定构建的 Paper 服务端下载项。
    pub async fn server_jar(&self, mc_version: &str) -> Result<DownloadItem, UpstreamError> {
        let url = format!("{}/versions/{mc_version}/builds", Self::API);
        let json = self.base.get_json(&url).await?;
        let builds = json["builds"]
            .as_array()
            .ok_or_else(|| UpstreamError::BadResponse(format!("Paper {mc_version} 无构建")))?;
        let build = builds.last().and_then(|b| b["build"].as_i64()).unwrap_or(0);
        let download_name = builds
            .last()
            .and_then(|b| b["downloads"]["application"]["name"].as_str())
            .ok_or_else(|| UpstreamError::BadResponse(format!("Paper {mc_version} 构建缺下载项")))?
            .to_string();
        let sha256 = builds
            .last()
            .and_then(|b| b["downloads"]["application"]["sha256"].as_str())
            .map(String::from);
        Ok(DownloadItem {
            url: format!("{}/versions/{mc_version}/builds/{build}/downloads/{download_name}", Self::API),
            sha1: None,
            sha256,
            file_name: format!("paper-{mc_version}-{build}.jar"),
            kind: DownloadKind::ServerJar,
        })
    }
}

// ---------------------------------------------------------------------------
// Fabric meta：loader / installer 版本与 bundle 服务端
// ---------------------------------------------------------------------------

pub struct FabricClient {
    base: HttpBase,
}

#[derive(Debug, Deserialize)]
pub struct FabricResolved {
    pub loader_version: String,
    pub installer_version: String,
    pub item: DownloadItem,
}

impl FabricClient {
    pub const META: &str = "https://meta.fabricmc.net/v2";

    pub fn new(base: HttpBase) -> Self {
        Self { base }
    }

    /// 解析给定 MC 版本的 loader / installer 并产出服务端 bundle 下载项。
    /// 注意：Fabric meta 不提供哈希，`item.sha256 = None`（文档需注明，
    /// 来源为官方 meta 域名 + HTTPS，满足官方渠道约束）。
    pub async fn resolve_server(&self, mc_version: &str) -> Result<FabricResolved, UpstreamError> {
        let loader_json = self.base.get_json(&format!("{}/versions/loader/{mc_version}", Self::META)).await?;
        let loader_version = loader_json
            .as_array()
            .and_then(|a| a.first())
            .and_then(|e| e["loader"]["version"].as_str())
            .ok_or_else(|| UpstreamError::BadResponse(format!("Fabric 无 {mc_version} 的 loader")))?;
        let installer_json = self.base.get_json(&format!("{}/versions/installer", Self::META)).await?;
        let installer_version = installer_json
            .as_array()
            .ok_or_else(|| UpstreamError::BadResponse("Fabric installer 清单缺失".into()))?
            .iter()
            .find(|e| e["stable"].as_bool().unwrap_or(false))
            .and_then(|e| e["version"].as_str())
            .ok_or_else(|| UpstreamError::BadResponse("Fabric 无稳定 installer".into()))?;
        Ok(FabricResolved {
            loader_version: loader_version.to_string(),
            installer_version: installer_version.to_string(),
            item: DownloadItem {
                url: format!(
                    "{}/versions/loader/{mc_version}/{loader_version}/{installer_version}/server/jar",
                    Self::META
                ),
                sha1: None,
                sha256: None,
                file_name: format!("fabric-server-{mc_version}.jar"),
                kind: DownloadKind::ServerJar,
            },
        })
    }
}

// ---------------------------------------------------------------------------
// Modrinth v2：检索、版本匹配、依赖闭包
// ---------------------------------------------------------------------------

pub struct ModrinthClient {
    base: HttpBase,
}

#[derive(Debug, Deserialize)]
struct ModrinthSearch {
    hits: Vec<SearchHit>,
}

#[derive(Debug, Deserialize)]
struct SearchHit {
    project_id: String,
    slug: String,
    title: String,
}

#[derive(Debug, Deserialize)]
struct ModrinthVersion {
    id: String,
    files: Vec<VersionFile>,
    dependencies: Vec<VersionDep>,
}

#[derive(Debug, Deserialize)]
struct VersionFile {
    url: String,
    filename: String,
    primary: bool,
    hashes: serde_json::Value,
}

#[derive(Debug, Deserialize)]
struct VersionDep {
    project_id: Option<String>,
    dependency_type: String,
}

impl ModrinthClient {
    pub const API: &str = "https://api.modrinth.com/v2";

    pub fn new(base: HttpBase) -> Self {
        Self { base }
    }

    /// 文本检索（别名表未命中时兜底），返回 (slug, title, project_id) 列表。
    pub async fn search(&self, query: &str) -> Result<Vec<(String, String, String)>, UpstreamError> {
        let url = format!(
            "{}/search?query={}&limit=5",
            Self::API,
            urlencoding_escape(query)
        );
        let search: ModrinthSearch = self.base.get_json(&url).await?.into();
        Ok(search
            .hits
            .into_iter()
            .map(|h| (h.slug, h.title, h.project_id))
            .collect())
    }

    /// 解析一个 mod 在 (mc, loader) 下的最新版本 + 递归依赖闭包 → ModRef。
    pub async fn resolve_mod(
        &self,
        project: &str,
        mc_version: &str,
        loader: &str,
        kb_alias: Option<&dyn Fn(&str) -> Option<String>>,
    ) -> Result<ModRef, UpstreamError> {
        self.resolve_mod_inner(project, mc_version, loader, &mut std::collections::HashMap::new())
            .await
    }

    fn facet(mc_version: &str, loader: &str) -> String {
        format!(
            r#"["versions:{}"]&loaders=["{loader}"]"#,
            mc_version.replace('"', "")
        )
    }

    async fn resolve_mod_inner(
        &self,
        project: &str,
        mc_version: &str,
        loader: &str,
        visited: &mut std::collections::HashMap<String, ModRef>,
    ) -> Result<ModRef, UpstreamError> {
        if let Some(cached) = visited.get(project) {
            return Ok(cached.clone());
        }
        let versions_url = format!(
            "{}/project/{project}/version?game_versions={}",
            Self::API,
            Self::facet(mc_version, loader)
        );
        let versions: Vec<ModrinthVersion> = self.base.get_json(&versions_url).await?.into();
        let version = versions
            .first()
            .ok_or(UpstreamError::BadResponse(format!(
                "mod {project} 没有 {mc_version}/{loader} 的可用版本"
            )))?
            .clone();
        let file = version
            .files
            .iter()
            .find(|f| f.primary)
            .or_else(|| version.files.first())
            .ok_or(UpstreamError::BadResponse(format!("mod {project} 版本无文件")))?;
        let sha1 = file.hashes["sha1"].as_str().unwrap_or_default().to_string();

        let mut deps = Vec::new();
        for dep in &version.dependencies {
            if dep.dependency_type != "required" {
                continue;
            }
            if let Some(dep_project) = &dep.project_id {
                // 依赖同样按 (mc, loader) 匹配，递归展开
                if let Ok(dep_ref) = self.resolve_mod_inner(dep_project, mc_version, loader, visited).await {
                    deps.push(dep_ref);
                }
            }
        }

        // project_id / slug 都可作为 project 标识；取文件名做展示名
        let project_id = visited.len().to_string(); // 防重复占位，真实 id 下面取
        let _ = project_id;
        let mod_ref = ModRef {
            project: project.to_string(),
            version_id: version.id.clone(),
            url: file.url.clone(),
            sha1,
            file_name: file.filename.clone(),
            deps,
        };
        visited.insert(project.to_string(), mod_ref.clone());
        Ok(mod_ref)
    }
}

/// 简单的 URL 查询参数转义（检索词含中文/空格）。
fn urlencoding_escape(s: &str) -> String {
    s.bytes()
        .map(|b| match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                (b as char).to_string()
            }
            _ => format!("%{b:02X}"),
        })
        .collect()
}

// ---------------------------------------------------------------------------
// Adoptium v3：受管 JRE 元数据（§8.8）
// ---------------------------------------------------------------------------

pub struct AdoptiumClient {
    base: HttpBase,
}

#[derive(Debug, Deserialize)]
pub struct JreAsset {
    pub release_name: String,
    pub download_url: String,
    pub file_name: String,
    pub sha256: Option<String>,
}

impl AdoptiumClient {
    pub const API: &str = "https://api.adoptium.net/v3";

    pub fn new(base: HttpBase) -> Self {
        Self { base }
    }

    /// 当前平台的官方 JRE（zip 免安装包）最新 GA 版本。
    pub async fn latest_jre(&self, java_major: u8) -> Result<JreAsset, UpstreamError> {
        let os = match std::env::consts::OS {
            "windows" => "windows",
            "macos" => "mac",
            _ => "linux",
        };
        let arch = match std::env::consts::ARCH {
            "x86_64" => "x64",
            "aarch64" => "aarch64",
            other => other,
        };
        let url = format!(
            "{API}/assets/latest/{java_major}/ga?os={os}&arch={arch}&image_type=jre",
            API = Self::API
        );
        let json = self.base.get_json(&url).await?;
        let arr = json
            .as_array()
            .and_then(|a| a.first())
            .ok_or_else(|| UpstreamError::BadResponse(format!("Adoptium 无 Java {java_major} JRE")))?;
        let release_name = arr["release_name"].as_str().unwrap_or_default().to_string();
        let package = &arr["binaries"][0]["package"];
        Ok(JreAsset {
            release_name,
            download_url: package["link"].as_str().unwrap_or_default().to_string(),
            file_name: package["name"].as_str().unwrap_or_default().to_string(),
            sha256: package["sha256"].as_str().map(String::from),
        })
    }
}

