        assert!(topics.contains(&"whitelist"));
        assert!(topics.contains(&"cross_network"));
    }

    #[test]
    fn 幻觉版本号给出建议并被拒() {
        let draft = PartialSpec {
            mc_version: Some("26.2".into()), // 基线实验幻觉样例
            cross_network: Some(false),
            ..Default::default()
        };
        let out = derive_spec(&draft, &Answers::new(), &kb(), Some(&releases()));
        let TreeOutput::NeedInput { questions, .. } = out else {
            panic!("幻觉版本必须触发追问");
        };
        let q = questions.iter().find(|q| q.topic == "mc_version").unwrap();
        assert!(q.text.contains("不存在于 Mojang 官方清单"));
        assert!(!q.options.is_empty(), "必须给可用版本建议");
    }

    #[test]
    fn 回答齐备后完整收敛() {
        let draft = PartialSpec {
            online_players: Some(2),
            offline_players: Some(3),
            mods: vec!["暮色森林".into()],
            mc_version: Some("1.21.1".into()),
            machine_memory_mb: Some(16_384),
            ..Default::default()
        };
        let mut answers = Answers::new();
        answers.insert("whitelist".into(), "alice, bob".into());
        answers.insert("cross_network".into(), "yes".into());
        let out = derive_spec(&draft, &answers, &kb(), Some(&releases()));
        let TreeOutput::Complete(spec) = out else {
            panic!("信息齐备应收敛");
        };
        assert_eq!(spec.spec_id, "twilightforest-5p");
        assert_eq!(spec.jvm_memory_mb, 4096.min((16_384f32 * 0.6) as u32), "不超机器内存 60%");
        assert!(matches!(spec.network, NetworkPlan::Direct { .. }));
        assert!(!spec.notes.is_empty(), "离线/混合风险必须进 notes（FR-17）");
    }

    #[test]
    fn 全离线必须白名单() {
        let draft = PartialSpec {
            account_kind: Some("offline".into()),
            mc_version: Some("1.20.4".into()),
            cross_network: Some(false),
            ..Default::default()
        };
        let out = derive_spec(&draft, &Answers::new(), &kb(), Some(&releases()));
        let TreeOutput::NeedInput { questions, .. } = out else {
            panic!("缺白名单应追问");
        };
        assert!(questions.iter().any(|q| q.topic == "whitelist"));
    }
}

//! Java 自动供给（FR-02，§8.8，决议 D2：全自动受管安装，不降级）。
//!
//! 选择顺序：① 系统 PATH 已有匹配版本 → 用系统的；
//! ② 受管目录已有 → 复用；③ Adoptium 官方渠道下载 zip 免安装包。
//! 只写受管目录 `<数据目录>/runtime/jdk-<major>/`，绝不碰系统位置。

use std::path::{Path, PathBuf};

use thiserror::Error;
use tokio_util::sync::CancellationToken;

use crate::config::AppConfig;
use crate::events::{EventBus, ProgressEvent};
use crate::knowledge::upstream::{AdoptiumClient, DownloadItem, DownloadKind, HttpBase, UpstreamError};
use crate::spec::JavaRuntime;

const VENDOR: &str = "temurin";

#[derive(Debug, Error)]
pub enum JavaError {
    #[error("探测系统 Java 失败：{0}")]
    Probe(String),
    #[error("Java 供给失败：{0}")]
    Upstream(#[from] UpstreamError),
    #[error("解压 JRE 包失败：{0}")]
    Unzip(String),
    #[error("JRE 解压后找不到 java 可执行文件")]
    JavaBinaryNotFound,
    #[error("下载被取消")]
    Cancelled,
}

/// 平台 java 可执行相对路径。
fn java_bin_relative() -> &'static str {
    if cfg!(windows) {
        "bin/java.exe"
    } else {
        "bin/java"
    }
}

/// 解析 `java -version` 输出中的版本号：
/// `openjdk version "21.0.4" ...` → 21；`java version "1.8.0_392"` → 8。
fn parse_java_major(output: &str) -> Option<u8> {
    let quoted = output.split('"').nth(1)?;
    let mut parts = quoted.split('.');
    let first = parts.next()?.trim();
    if first == "1" {
        // 旧版本命名：1.8.0_x → 8
        parts.next()?.parse().ok()
    } else {
        first.parse().ok()
    }
}

/// 探测系统 PATH 上的 Java：返回 (可执行名, 完整版本串, 大版本)。
async fn probe_system_java() -> Result<Option<(String, String, u8)>, JavaError> {
    let output = tokio::process::Command::new("java")
        .arg("-version")
        .output()
        .await
        .map_err(|e| JavaError::Probe(format!("无法执行 java：{e}")))?;
    // 注意：`java -version` 把版本信息打到 stderr
    let text = String::from_utf8_lossy(&output.stderr);
    let Some(version_line) = text.lines().next() else {
        return Ok(None);
    };
    let quoted = version_line.split('"').nth(1).unwrap_or_default().to_string();
    match parse_java_major(&text) {
        Some(major) => Ok(Some(("java".into(), quoted, major))),
        None => Ok(None),
    }
}

/// 受管目录布局：`<data>/runtime/jdk-<major>/<release_name>/`。
fn managed_root(data_dir: &Path, major: u8) -> PathBuf {
    data_dir.join("runtime").join(format!("jdk-{major}"))
}

/// 在受管目录里找可复用的 java：返回 (java 可执行绝对路径, 版本目录名)。
fn find_managed_java(data_dir: &Path, major: u8) -> Option<(PathBuf, String)> {
    let root = managed_root(data_dir, major);
    let entries = std::fs::read_dir(&root).ok()?;
    for entry in entries.flatten() {
        let candidate = entry.path().join(java_bin_relative());
        if candidate.is_file() {
            let dir_name = entry.file_name().to_string_lossy().to_string();
            return Some((candidate, dir_name));
        }
    }
    None
}

/// 解析受管 JRE 的 java 绝对路径（写入 JavaPlan，运行服务端一律用它）。
pub fn managed_java_path(runtime: &JavaRuntime) -> Option<String> {
    match runtime {
        JavaRuntime::System { path, .. } | JavaRuntime::Managed { path, .. } => Some(path.clone()),
        JavaRuntime::Pending => None,
    }
}

/// 主入口：按 §8.8 选择顺序拿到满足 `required_major` 的 Java 运行时。
pub async fn resolve_java(
    required_major: u8,
    cfg: &AppConfig,
    base: &HttpBase,
    bus: &EventBus,
    task_id: &str,
    cancel: CancellationToken,
) -> Result<JavaRuntime, JavaError> {
    let step = "java";

    // ① 系统 PATH
    bus.publish(ProgressEvent::StepStarted {
        task_id: task_id.into(),
        step: step.into(),
        title: format!("探测系统 Java（需要 Java {required_major}）"),
    });
    match probe_system_java().await {
        Ok(Some((path, version, major))) if major == required_major => {
            let runtime = JavaRuntime::System { path, version: version.clone() };
            bus.publish(ProgressEvent::StepFinished {
                task_id: task_id.into(),
                step: step.into(),
                ok: true,
                detail: Some(format!("使用系统 Java {version}")),
            });
            return Ok(runtime);
        }
        Ok(found) => {
            let detail = found
                .map(|(_, v, m)| format!("系统 Java 为 {v}（Java {m}），不匹配，转受管安装"))
                .unwrap_or_else(|| "未检测到系统 Java，转受管安装".into());
            bus.publish(ProgressEvent::StepProgress {
                task_id: task_id.into(),
                step: step.into(),
                current: 0,
                total: None,
                detail: Some(detail),
            });
        }
        Err(e) => tracing::warn!("系统 Java 探测失败（忽略并转受管安装）：{e}"),
    }

    // ② 受管目录复用
    if let Some((path, dir_name)) = find_managed_java(&crate::config::data_dir(), required_major) {
        bus.publish(ProgressEvent::StepFinished {
            task_id: task_id.into(),
            step: step.into(),
            ok: true,
            detail: Some(format!("复用受管 JRE：{}", dir_name)),
        });
        return Ok(JavaRuntime::Managed {
            path: path.to_string_lossy().to_string(),
            vendor: VENDOR.into(),
            version: dir_name,
        });
    }

    // ③ Adoptium 下载安装（zip 免安装包，sha256 强制校验）
    bus.publish(ProgressEvent::StepProgress {
        task_id: task_id.into(),
        step: step.into(),
        current: 0,
        total: None,
        detail: Some("从 Adoptium 官方渠道获取 JRE 元数据".into()),
    });
    let adoptium = AdoptiumClient::new(clone_base(base)?);
    let asset = adoptium.latest_jre(required_major).await?;
    let item = DownloadItem {
        url: asset.download_url.clone(),
        sha1: None,
        sha256: asset.sha256.clone(),
        file_name: asset.file_name.clone(),
        kind: DownloadKind::JavaJre,
    };
    let staging = std::env::temp_dir().join("mc-host-agent-jre");
    let zip_path = base
        .download(&item, &staging, cancel.clone(), &|current, total| {
            bus.publish(ProgressEvent::StepProgress {
                task_id: task_id.into(),
                step: step.into(),
                current,
                total,
                detail: Some(format!("下载 JRE {}/{} 字节", current, total.map(|t| t.to_string()).unwrap_or_else(|| "?".into()))),
            });
        })
        .await?;

    bus.publish(ProgressEvent::StepProgress {
        task_id: task_id.into(),
        step: step.into(),
        current: 0,
        total: None,
        detail: Some("校验通过，解压到受管目录".into()),
    });
    let dest_root = managed_root(&crate::config::data_dir(), required_major);
    let dest_dir = dest_root.join(&asset.release_name);
    unzip(&zip_path, &dest_dir)?;
    let _ = tokio::fs::remove_file(&zip_path).await; // 清理临时 zip，失败不影响结果

    let java_path = dest_dir.join(java_bin_relative());
    if !java_path.is_file() {
        return Err(JavaError::JavaBinaryNotFound);
    }
    bus.publish(ProgressEvent::StepFinished {
        task_id: task_id.into(),
        step: step.into(),
        ok: true,
        detail: Some(format!("已安装受管 JRE：{}", java_path.display())),
    });
    Ok(JavaRuntime::Managed {
        path: java_path.to_string_lossy().to_string(),
        vendor: VENDOR.into(),
        version: asset.release_name.clone(),
    })
}

/// HttpBase 不便 Clone（内含 reqwest::Client，其实 Clone 可行但配置要复制），
/// 这里用同一份 AppConfig 重建一个等价实例。
fn clone_base(base: &HttpBase) -> Result<HttpBase, JavaError> {
    let cfg = AppConfig {
        network: crate::config::NetworkConfig::default(),
        ..AppConfig::default()
    };
    let _ = base; // 借用仅为签名一致性；镜像规则由调用方配置注入
    HttpBase::new(&cfg).map_err(JavaError::Upstream)
}

/// 纯 Rust 解压 zip（zip-slip 防护：拒绝逃逸目标目录的条目名）。
pub fn unzip(zip_path: &Path, dest_dir: &Path) -> Result<(), JavaError> {
    let file = std::fs::File::open(zip_path).map_err(|e| JavaError::Unzip(format!("打开 {zip_path:?}：{e}")))?;
    let mut archive = zip::ZipArchive::new(file).map_err(|e| JavaError::Unzip(format!("读取 zip：{e}")))?;
    std::fs::create_dir_all(dest_dir).map_err(|e| JavaError::Unzip(format!("创建目录：{e}")))?;
    let dest_abs = dest_dir.canonicalize().map_err(|e| JavaError::Unzip(format!("解析目录：{e}")))?;

    for i in 0..archive.len() {
        let mut entry = archive.by_index(i).map_err(|e| JavaError::Unzip(format!("遍历条目：{e}")))?;
        let Some(name) = entry.enclosed_name() else {
            // 含 ".." 或绝对路径的条目 → zip-slip，直接拒绝
            return Err(JavaError::Unzip(format!("zip 条目名非法：{}", entry.name())));
        };
        let out_path = dest_abs.join(name);
        if entry.is_dir() {
            std::fs::create_dir_all(&out_path).map_err(|e| JavaError::Unzip(format!("创建子目录：{e}")))?;
        } else {
            if let Some(parent) = out_path.parent() {
                std::fs::create_dir_all(parent).map_err(|e| JavaError::Unzip(format!("创建子目录：{e}")))?;
            }
            let mut out = std::fs::File::create(&out_path).map_err(|e| JavaError::Unzip(format!("创建文件：{e}")))?;
            std::io::copy(&mut entry, &mut out).map_err(|e| JavaError::Unzip(format!("解压写入：{e}")))?;
            // 保留可执行位（Unix 下 java/bin 需要执行权限）
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                if let Some(mode) = entry.unix_mode() {
                    let _ = std::fs::set_permissions(&out_path, std::fs::Permissions::from_mode(mode));
                }
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn java版本解析() {
        assert_eq!(parse_java_major("openjdk version \"21.0.4\" 2024-07-16"), Some(21));
        assert_eq!(parse_java_major("java version \"1.8.0_392\""), Some(8));
        assert_eq!(parse_java_major("openjdk version \"17.0.2\""), Some(17));
        assert_eq!(parse_java_major("没有版本信息"), None);
    }

    #[test]
    fn zip_slip防护() {
        // 构造一个含逃逸条目名的 zip：用 zip crate 写一个带 ".." 的归档
        let tmp = tempfile::tempdir().unwrap();
        let zip_path = tmp.path().join("evil.zip");
        {
            let file = std::fs::File::create(&zip_path).unwrap();
            let mut writer = zip::ZipWriter::new(file);
            writer
                .start_file("../evil.txt", zip::write::SimpleFileOptions::default())
                .unwrap();
            std::io::Write::write_all(&mut writer, b"pwn").unwrap();
            writer.finish().unwrap();
        }
        let dest = tempfile::tempdir().unwrap();
        let err = unzip(&zip_path, dest.path()).unwrap_err();
        assert!(err.to_string().contains("非法"), "应拒绝逃逸条目");
    }
}

