/// GET 并解析为 JSON。
pub async fn get_json(&self, url: &str) -> Result<serde_json::Value, UpstreamError> {
    let url = self.apply_mirrors(url);
    let resp = self.http.get(&url).send().await?;
    let status = resp.status();
    let text = resp.text().await.unwrap_or_default();
    if !status.is_success() {
        return Err(UpstreamError::Status { url, status: status.as_u16(), body: text });
    }
    serde_json::from_str(&text).map_err(|e| UpstreamError::Json { url, source: e })
}

/// GET 并直接反序列化为目标类型（内部走 get_json）。
pub async fn get_typed<T: serde::de::DeserializeOwned>(&self, url: &str) -> Result<T, UpstreamError> {
    let url = self.apply_mirrors(url);
    let value = self.get_json(&url).await?;
    serde_json::from_value(value).map_err(|e| UpstreamError::Json { url, source: e })
}

