/// GET 并解析为 JSON。瞬时网络失败自动重试（NFR-3）。
pub async fn get_json(&self, url: &str) -> Result<serde_json::Value, UpstreamError> {
    let url = self.apply_mirrors(url);
    let mut attempt = 0;
    loop {
        attempt += 1;
        let resp = self.http.get(&url).send().await;
        // 瞬时失败（连接/超时/中断）重试后重新发起
        if let Err(e) = &resp {
            if attempt < 3 && is_transient_reqwest(e) {
                tracing::warn!("GET {url} 第 {attempt} 次失败，重试：{e}");
                tokio::time::sleep(backoff(attempt)).await;
                continue;
            }
            return Err(e.clone().into());
        }
        let resp = resp.unwrap_or_else(|_| unreachable!("上方已处理 Err"));
        let status = resp.status();
        let text = resp.text().await;
        if let Err(e) = &text {
            if attempt < 3 && is_transient_reqwest(e) {
                tracing::warn!("读取 {url} 响应体第 {attempt} 次失败，重试：{e}");
                tokio::time::sleep(backoff(attempt)).await;
                continue;
            }
            return Err(e.clone().into());
        }
        let text = text.unwrap_or_else(|_| unreachable!("上方已处理 Err"));
        if !status.is_success() {
            return Err(UpstreamError::Status {
                url,
                status: status.as_u16(),
                body: text,
            });
        }
        return serde_json::from_str(&text).map_err(|e| UpstreamError::Json { url, source: e });
    }
}

